#pragma once

#include "gui_forms/binding/property_cell/property_cell.hpp"
#include "gui_forms/types.hpp"

#include <cstdint>
#include <optional>
#include <string>
#include <utility>

namespace gui_forms {

// ColorValueEditor's property capabilities (property-capabilities study, sections
// 2, 14 and 15). Generated by tools/property_codemod.py from
// tools/property_families/color_value_editor.json: edit the config, not this file.
//
// Each is a standard-layout struct whose only member is its property's
// cell, taken by the declaring class as a base. A write
// `(*control).x = value;` runs `assign`: the declaring class's
// prepare_write hook (require_mutable first, then the value's checks), the
// compare and store, then the written hook (the touch, side effects and the
// change event, through the protected virtual on_<property>_changed() where
// Windows Forms has an overridable On<Property>Changed; other properties
// have no hook, and a subclass subscribes to their change events instead). A read is
// `(*control).x.read()`.

// The edited colour; a view, since committing the text moves it and an equal write still restores the text and the normal status. A write raises no event.
template <typename Declaring>
struct ColorValueEditorValueCapability {
    PropertyView<Color, ColorValueEditorValueCapability<Declaring>> value;

    static void assign(ColorValueEditorValueCapability& capability, Color incoming) {
        Declaring& control = static_cast<Declaring&>(capability);
        control.write_view(std::as_const(capability.value), std::move(incoming));
    }

    static Color read(const ColorValueEditorValueCapability& capability) {
        const Declaring& control = static_cast<const Declaring&>(capability);
        Color current = control.read_view(capability.value);
        return current;
    }
};

// The width of the colour swatch before the text, 12 to 96 (std::invalid_argument otherwise).
template <typename Declaring>
struct ColorValueEditorSwatchWidthCapability {
    PropertyCell<double, ColorValueEditorSwatchWidthCapability<Declaring>> swatch_width{30.0};

    static void assign(ColorValueEditorSwatchWidthCapability& capability, double incoming) {
        Declaring& control = static_cast<Declaring&>(capability);
        control.prepare_write(std::as_const(capability.swatch_width), incoming);
        if (!capability.swatch_width.replace(std::move(incoming))) return;
        control.written(std::as_const(capability.swatch_width));
    }
};

// Every ColorValueEditor capability, in the order the declaring class takes them.
template <typename Declaring>
struct ColorValueEditorCapabilities : public ColorValueEditorValueCapability<Declaring>,
                                      public ColorValueEditorSwatchWidthCapability<Declaring> {};

} // namespace gui_forms
